#include <string.h>
static const int steps[89]={7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767};
static const int indices[8]={-1,-1,-1,-1,2,4,6,8};
static int clamp(int v,int a,int b){return v<a?a:v>b?b:v;}
static uint16_t u16(const uint8_t*p){return p[0]|(p[1]<<8);}
static uint32_t u32(const uint8_t*p){return u16(p)|((uint32_t)u16(p+2)<<16);}
static void w16(uint8_t*p,uint16_t n){p[0]=n;p[1]=n>>8;}
static void w32(uint8_t*p,uint32_t n){w16(p,n);w16(p+2,n>>16);}
static uint32_t crc(const uint8_t*p,size_t n){uint32_t c=~0u;while(n--){c^=*p++;for(int i=0;i<8;i++)c=(c>>1)^((0u-(c&1))&0xedb88320);}return ~c;}
static int nibble(int code,int*predictor,int*index){int step=steps[*index],d=step>>3;if(code&1)d+=step>>2;if(code&2)d+=step>>1;if(code&4)d+=step;*predictor=clamp(*predictor+((code&8)?-d:d),-32768,32767);*index=clamp(*index+indices[code&7],0,88);return *predictor;}
void radpcm_encode(const int16_t*pcm,uint8_t raw[328],uint16_t frame,int*p,int*idx){memset(raw,0,328);w16(raw,frame);w16(raw+2,*p);raw[4]=*idx;w16(raw+6,320);for(int i=0;i<640;i++){int diff=pcm[i]-*p,code=0,step=steps[*idx];if(diff<0){code=8;diff=-diff;}if(diff>=step){code|=4;diff-=step;}if(diff>=step/2){code|=2;diff-=step/2;}if(diff>=step/4)code|=1;nibble(code,p,idx);if(!(i&1))raw[8+i/2]=code<<4;else raw[8+i/2]|=code;}}
bool radpcm_decode(const uint8_t r[328],int16_t out[640]){if(r[4]>88||r[6]!=64)return false;int p=(int16_t)u16(r+2),i=r[4];for(int j=0;j<320;j++){out[j*2]=nibble(r[8+j]>>4,&p,&i);out[j*2+1]=nibble(r[8+j]&15,&p,&i);}return true;}
bool voice_parse(const uint8_t*p,size_t n,voice_packet_t*v){if(!p||!v||n<80||n>1400||u16(p)!=1||u32(p+30)!=n||crc(p+64,n-64)!=u32(p+36))return false;memset(v,0,sizeof(*v));v->count=u16(p+34);if(v->count<1||v->count>6)return false;v->uid=u32(p+6);v->base=u32(p+22);v->timestamp=u32(p+26);v->server=u32(p+41);for(int i=0;i<12&&p[10+i];i++){if(p[10+i]<32||p[10+i]>126)return false;v->call[i]=p[10+i];}size_t pos=64;unsigned prev=0;for(int i=0;i<v->count;i++){if(pos+16>n)return false;unsigned seq=u16(p+pos),len=u16(p+pos+2),mode=p[pos+8];if(!seq||seq<=prev||len<=16||pos+len>n||u16(p+pos+9)!=len-8||(mode!=1&&mode!=2))return false;v->mode[i]=mode;v->len[i]=len-16;v->raw[i]=p+pos+16;if(mode==2&&(v->len[i]!=328||v->raw[i][4]>88||v->raw[i][6]!=64))return false;prev=seq;pos+=len;}return pos==n;}
size_t voice_pack(uint8_t*out,size_t cap,const uint8_t*frames,int count,uint32_t uid,const char*call,uint32_t server,uint32_t base,uint32_t stamp,uint16_t first){size_t n=64+344*count;if(count<1||count>3||!first||cap<n||strlen(call)>12)return 0;memset(out,0,n);w16(out,1);w32(out+2,0x1791);w32(out+6,uid);memcpy(out+10,call,strlen(call));w32(out+22,base);w32(out+26,stamp);w32(out+30,n);w16(out+34,count);out[40]=7;w32(out+41,server);for(int i=0;i<count;i++){uint8_t*f=out+64+i*344;w16(f,i+1);w16(f+2,344);f[8]=2;w16(f+9,336);memcpy(f+16,frames+i*328,328);}w32(out+36,crc(out+64,n-64));return n;}
